from sqlalchemy import case, func, or_, select
from sqlalchemy.ext.asyncio import AsyncSession

from app.config import settings
from app.models import AnswerLog, User
from app.schemas.pricing import (
    ChatModelPricing,
    EmbeddingModelPricing,
    PricingDefaults,
    PricingTableResponse,
    TokenBilling,
    UserTokenUsage,
    UserTokenUsageResponse,
)

BILLING_CURRENCY = "INR"
BILLING_UNIT = "per non-cached token"
BILLING_NOTE = (
    "Cache hits and RAG are free. Answers generated by the model or researched from other sources are "
    "charged per token; when no model tokens were used the answer's tokens are estimated (about 4 characters each)."
)
CACHE_HITS = ("exact_hit", "semantic_hit")


def get_billing() -> TokenBilling:
    return TokenBilling(
        currency=BILLING_CURRENCY,
        rate_per_token=settings.answers_inr_per_token,
        unit=BILLING_UNIT,
        note=BILLING_NOTE,
    )


def get_pricing_table() -> PricingTableResponse:
    return PricingTableResponse(
        currency=settings.pricing_currency,
        effective_date=settings.pricing_effective_date,
        unit="per 1,000,000 tokens",
        source="PRICING_TABLE / EMBEDDING_PRICING_TABLE",
        is_estimate=True,
        note="Costs are estimates from the configured pricing tables, not provider billing.",
        defaults=PricingDefaults(
            chat_prompt_per_million=settings.chat_prompt_price_per_million,
            chat_completion_per_million=settings.chat_completion_price_per_million,
            embedding_per_million=settings.embedding_price_per_million,
        ),
        billing=get_billing(),
        chat_models=sorted(
            (
                ChatModelPricing(
                    model=model,
                    prompt_per_million=float(prices.get("prompt", 0.0)),
                    completion_per_million=float(prices.get("completion", 0.0)),
                )
                for model, prices in settings.PRICING_TABLE.items()
            ),
            key=lambda item: item.model,
        ),
        embedding_models=sorted(
            (
                EmbeddingModelPricing(model=model, price_per_million=float(price))
                for model, price in settings.EMBEDDING_PRICING_TABLE.items()
            ),
            key=lambda item: item.model,
        ),
    )


async def get_user_token_usage(
    session: AsyncSession, owner_id: int | None = None, end_user: str | None = None
) -> UserTokenUsageResponse:
    """Per-caller billing. ``owner_id`` restricts every row to that account (ownership enforced in SQL)."""
    cached = or_(
        AnswerLog.cache_status.in_(CACHE_HITS),
        AnswerLog.answered_by == "cache",
    )
    rows = (
        await session.execute(
            select(
                AnswerLog.user_id,
                AnswerLog.end_user,
                func.count(AnswerLog.id),
                func.sum(case((cached, 1), else_=0)),
                func.sum(case((cached, 0), else_=1)),
                func.sum(AnswerLog.total_tokens),
                func.sum(AnswerLog.billable_tokens),
                func.sum(AnswerLog.cost_inr),
            )
            .where(AnswerLog.status == "ok", *([AnswerLog.user_id == owner_id] if owner_id is not None else []),
                *([AnswerLog.end_user == end_user] if end_user is not None else []))
            .group_by(AnswerLog.user_id, AnswerLog.end_user)
        )
    ).all()
    account_query = select(User.id, User.username, User.email, User.role)
    if owner_id is not None:
        account_query = account_query.where(User.id == owner_id)
    elif end_user is not None:
        account_query = account_query.where(User.id == -1)  # an end user has no gateway account row
    users = (await session.execute(account_query)).all()
    accounts = {int(user[0]): {"username": user[1], "email": user[2], "role": user[3]} for user in users}

    items = []
    for row in rows:
        user_id = int(row[0]) if row[0] is not None else None
        account = accounts.get(user_id, {}) if user_id is not None else {}
        items.append(
            UserTokenUsage(
                user_id=user_id,
                username=account.get("username"),
                email=account.get("email"),
                role=account.get("role"),
                end_user=row[1],
                answers=int(row[2] or 0),
                cached_answers=int(row[3] or 0),
                uncached_answers=int(row[4] or 0),
                total_tokens=int(row[5] or 0),
                billable_tokens=int(row[6] or 0),
                cost_inr=round(float(row[7] or 0.0), 2),
            )
        )

    seen_user_ids = {item.user_id for item in items if item.user_id is not None}
    for user_id, username, email, role in users:
        uid = int(user_id)
        if uid in seen_user_ids:
            continue
        items.append(UserTokenUsage(user_id=uid, username=username, email=email, role=role))

    items.sort(
        key=lambda item: (
            -item.cost_inr,
            -item.billable_tokens,
            item.username or "",
            item.end_user or "",
        )
    )
    return UserTokenUsageResponse(
        scope="user" if end_user is not None else "all" if owner_id is None else "own",
        currency=BILLING_CURRENCY,
        rate_per_token=settings.answers_inr_per_token,
        unit=BILLING_UNIT,
        note=BILLING_NOTE,
        total_billable_tokens=sum(item.billable_tokens for item in items),
        total_cost_inr=round(sum(item.cost_inr for item in items), 2),
        items=items,
    )
